import{c as s,$ as a,Q as n,j as o,g as e,o as r,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const b=JSON.parse('{"title":"Счета и кошельки","description":"Практическое руководство по учету наличных денег, банковских карт, вкладов, валютных счетов и цифровых средств в ОмниКрафт ЕРП.","frontmatter":{"title":"Счета и кошельки","description":"Практическое руководство по учету наличных денег, банковских карт, вкладов, валютных счетов и цифровых средств в ОмниКрафт ЕРП.","datePublished":"2026-10-28","dateModified":"2026-11-15","order":15},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/accounts.md","filePath":"ru/docs/spaces/moy-kapital/accounts.md","lastUpdated":1794700800000}'),c={name:"ru/docs/spaces/moy-kapital/accounts.md"},p={id:"счета-и-кошельки-ликвидныи-контур-мастера",tabindex:"-1"};function g(m,t,h,x,u,f){const l=a("DocIcon");return n(),o("div",null,[e("h1",p,[r(l,{name:"capital"}),t[0]||(t[0]=i(" Счета и кошельки: Ликвидный контур мастера ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#счета-и-кошельки-ликвидныи-контур-мастера","aria-label":'Permalink to "Счета и кошельки: Ликвидный контур мастера"'},"​",-1))]),t[2]||(t[2]=d('<p>Вкладка <strong>«Счета и кошельки»</strong> — это отправная точка ликвидного контура мастера в пространстве «Мой капитал». Здесь сосредоточены все доступные денежные средства, которые не вовлечены непосредственно в текущий производственный цикл мастерской: наличные сбережения в сейфе или кошельке, дебетовые банковские карты, накопительные вклады, валютные резервы и цифровые расчетные средства.</p><p>Регулярная актуализация остатков на этих счетах формирует фундамент для автоматического расчета личных расходов по методу балансовой дельты капитала. Мастеру не нужно ежедневно фиксировать мелкие бытовые чеки: достаточно поддерживать реальные суммы на ключевых счетах, а система самостоятельно сопоставит изменения с доходами цехов.</p><hr><h2 id="сводныи-баланс-ликвидности-и-валютныи-пересчет" tabindex="-1">Сводный баланс ликвидности и валютный пересчет <a class="header-anchor" href="#сводныи-баланс-ликвидности-и-валютныи-пересчет" aria-label="Permalink to &quot;Сводный баланс ликвидности и валютный пересчет&quot;">​</a></h2><p>В верхней части экрана расположена карточка общего ликвидного баланса мастера:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Иконка кошелька] ВСЕГО НА СЧЕТАХ: 1 250 000,00 ₽</span></span></code></pre></div><p>Индикатор объединяет все заведенные счета и автоматически приводит остатки к базовой валюте учета (по умолчанию — российский рубль).</p><p>Для счетов в базовой валюте коэффициент пересчета всегда равен 1,00. Если счет открыт в иностранной валюте или расчетных стейблкоинах, система пересчитывает его баланс по формуле:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Валютный стандарт</span><div class="formula-heading">Пересчет валютного остатка в базовую валюту</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Базовый эквивалент (₽)</span><span class="math-op">=</span><span class="math-var">Остаток в валюте счета</span><span class="math-op">×</span><span class="math-var">Курс к базовой валюте</span></div></div><div class="formula-card-bottom"><p>Курсы валют обновляются централизованно через диалог курсов либо задаются индивидуально в параметрах счета. При изменении курса балансы всех зависимых счетов пересчитываются мгновенно.</p></div></div><hr><h2 id="два-режима-добавления-одиночныи-счет-и-банк" tabindex="-1">Два режима добавления: одиночный счет и банк <a class="header-anchor" href="#два-режима-добавления-одиночныи-счет-и-банк" aria-label="Permalink to &quot;Два режима добавления: одиночный счет и банк&quot;">​</a></h2><p>При нажатии кнопки <strong>«Добавить счет»</strong> в правом верхнем углу открывается окно с переключателем режимов создания:</p><ol><li><strong>Режим «Одиночный счет»:</strong> лаконичная форма для обособленных позиций — наличные деньги в сейфе цеха, карманные средства, накопительный конверт или отдельная кредитная карта.</li><li><strong>Режим «Группа / Банк / Хранилище»:</strong> мультивалютный контейнер, позволяющий за один шаг внести банковское учреждение со всеми открытыми в нем продуктами (например, зарплатная карта, валютный счет и накопительный вклад).</li></ol><div class="tip custom-block"><p class="custom-block-title">Быстрый ввод нескольких счетов банка</p><p>В режиме группы используйте кнопку <strong>«Добавить еще валюту / счет в группу»</strong>. Вы можете динамически прикрепить к одному банку любое количество счетов с индивидуальными остатками, валютами и служебными комментариями.</p></div><hr><h2 id="справочник-реквизитов-счета" tabindex="-1">Справочник реквизитов счета <a class="header-anchor" href="#справочник-реквизитов-счета" aria-label="Permalink to &quot;Справочник реквизитов счета&quot;">​</a></h2><p>При регистрации каждого счета заполняются следующие параметры:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Поле ввода</th><th style="text-align:left;">Назначение и формат</th><th style="text-align:left;">Пример значения</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>«Наименование счета»</strong></td><td style="text-align:left;">Понятное имя счета, отражающее его назначение</td><td style="text-align:left;"><em>Основная дебетовая карта</em>, <em>Сейф мастерской</em></td></tr><tr><td style="text-align:left;"><strong>«Группа (Банк)»</strong></td><td style="text-align:left;">Название финансового учреждения или хранилища</td><td style="text-align:left;"><em>Т-Банк</em>, <em>Сбер</em>, <em>Наличные резервы</em></td></tr><tr><td style="text-align:left;"><strong>«Категория группы»</strong></td><td style="text-align:left;">Классификатор контейнера для структурирования экрана</td><td style="text-align:left;"><em>Банки и вклады</em>, <em>Криптокошельки</em>, <em>Наличные</em></td></tr><tr><td style="text-align:left;"><strong>«Тип счета»</strong></td><td style="text-align:left;">Категория ликвидности инструмента</td><td style="text-align:left;"><em>Карта</em>, <em>Вклад</em>, <em>Наличные</em>, <em>Электронный кошелек</em>, <em>Криптовалюта</em></td></tr><tr><td style="text-align:left;"><strong>«Валюта счета»</strong></td><td style="text-align:left;">Выбор из предустановленного списка или ввод собственного тикера</td><td style="text-align:left;"><em>рубли (₽)</em>, <em>доллары ($)</em>, <em>евро (€)</em>, <em>USDT</em>, <em>USDC</em></td></tr><tr><td style="text-align:left;"><strong>«Остаток и курс»</strong></td><td style="text-align:left;">Текущая сумма на счете и множитель пересчета к базовой валюте</td><td style="text-align:left;"><em>150 000,00 ₽</em>, <em>1 200,00 $ (курс 93,50)</em></td></tr><tr><td style="text-align:left;"><strong>«Ссылка на онлайн-банк»</strong></td><td style="text-align:left;">Прямой веб-адрес личного кабинета банка для быстрого перехода</td><td style="text-align:left;"><code>https://ib.tbank.ru/</code></td></tr><tr><td style="text-align:left;"><strong>«Заметки»</strong></td><td style="text-align:left;">Служебные детали (условия начисления процентов, дата окончания вклада)</td><td style="text-align:left;"><em>Выплата процентов 15 числа каждого месяца</em></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Настройка типов и категорий</p><p>Справочники типов счетов и категорий групп не зашиты жестко. Нажатие на значок карандаша рядом с выпадающим списком позволяет переименовывать категории, добавлять собственные типы и упорядочивать их под свою структуру активов.</p></div><hr><h2 id="карточки-групп-и-организация-реестра" tabindex="-1">Карточки групп и организация реестра <a class="header-anchor" href="#карточки-групп-и-организация-реестра" aria-label="Permalink to &quot;Карточки групп и организация реестра&quot;">​</a></h2><p>Счета, объединенные общим именем группы, автоматически группируются на экране в наглядные сводные карточки:</p><ul><li><strong>Шапка группы:</strong> название банка, бейдж категории и счетчик активных счетов;</li><li><strong>Сводный баланс группы:</strong> совокупная сумма всех вложенных счетов, приведенная к базовой валюте;</li><li><strong>Строки счетов:</strong> список позиций с отображением остатка в оригинальной валюте, рублевого эквивалента и кнопки быстрого перехода в онлайн-банк;</li><li><strong>Быстрое пополнение (+):</strong> кнопка в правом верхнем углу карточки открывает диалог добавления нового счета с автоматически подставленным именем этой группы;</li><li><strong>Упорядочивание (стрелки ↑ и ↓):</strong> ручное перемещение карточки группы выше или ниже по экрану;</li><li><strong>Управление группой (карандаш):</strong> комплексное редактирование — переименование группы с каскадным обновлением связанных счетов, смена категории и перестановка счетов внутри группы.</li></ul><hr><h2 id="режимы-отображения-плитка-и-полосы" tabindex="-1">Режимы отображения: плитка и полосы <a class="header-anchor" href="#режимы-отображения-плитка-и-полосы" aria-label="Permalink to &quot;Режимы отображения: плитка и полосы&quot;">​</a></h2><p>На панели инструментов вкладки расположен переключатель плотности интерфейса:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="7" height="7" x="3" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="14" rx="1"></rect><rect width="7" height="7" x="3" y="14" rx="1"></rect></svg></span><span><strong>Режим «Плитка» (Колонки):</strong> Просторная блочная сетка, оптимизированная для широких мониторов. Карточки распределяются по адаптивным колонкам с группировкой по категориям.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="8" x2="21" y1="6" y2="6"></line><line x1="8" x2="21" y1="12" y2="12"></line><line x1="8" x2="21" y1="18" y2="18"></line><line x1="3" x2="3.01" y1="6" y2="6"></line><line x1="3" x2="3.01" y1="12" y2="12"></line><line x1="3" x2="3.01" y1="18" y2="18"></line></svg></span><span><strong>Режим «Полосы» (Плотный список):</strong> Компактный вертикальный реестр в формате аккордеона. Позволяет быстро просматривать десятки счетов без лишней прокрутки экрана.</span></li></ul><div class="tip custom-block"><p class="custom-block-title">Глобальное управление аккордеоном</p><p>В режиме полос на панели инструментов появляется кнопка <strong>«↕»</strong>. Она позволяет в один клик свернуть или развернуть все группы счетов одновременно.</p></div><hr><h2 id="архивация-и-мягкое-удаление-счетов" tabindex="-1">Архивация и мягкое удаление счетов <a class="header-anchor" href="#архивация-и-мягкое-удаление-счетов" aria-label="Permalink to &quot;Архивация и мягкое удаление счетов&quot;">​</a></h2><p>Если банковская карта заблокирована, вклад закрыт или электронный кошелек больше не используется, удалять запись из базы не требуется — отправьте ее в архив:</p><ol><li>Откройте диалог редактирования счета или вызовите контекстное меню карточки;</li><li>Нажмите кнопку <strong>«В архив»</strong>. Счет мгновенно исчезнет из активного списка и перестанет учитываться в текущем балансе ликвидности;</li><li>Если все счета группы перенесены в архив, вся карточка банка автоматически скрывается с активного экрана.</li></ol><div class="warning custom-block"><p class="custom-block-title">Сохранение истории балансовой дельты</p><p>Физическое удаление счета безвозвратно стирает историю денежных потоков. Архивация сохраняет балансовый след для ретроспективной аналитики капитала, исключая искажение расчетов за прошлые месяцы.</p></div><p>Для просмотра скрытых позиций нажмите кнопку <strong>«Архив»</strong> (иконка коробки) на панели инструментов. В архивном режиме счета можно вернуть в активный учет либо удалить окончательно с соблюдением системного регламента мягкого удаления.</p>',34))])}const v=s(c,[["render",g]]);export{b as __pageData,v as default};
